-- Generated: 2026-08-31 (this migration file's authoring date)
-- All 11 questions were generated by the real n8n large-scale question
-- generation pipeline (n8n/workflows/question-generation-enum-test.json,
-- Faz 152's fixed AI Judge, Topic Selection -> {topicSlug: "scanner",
-- overrideCount: 8}), grounded in content/en/scanner.md and
-- content/tr/scanner.md. 8 of the 11 (394, 396, 397, 401, 402, 404, 405,
-- 406) were auto-published by the AI Judge's own APPROVE verdict via
-- QuestionReviewService#autoPublish. 3 (395, 398, 400) were left
-- PENDING_REVIEW by AI Judge REJECT verdicts that, on independent human
-- ADMIN review against the lesson content, were found to be false
-- negatives -- the judge's stated rejection reasons in each case actually
-- described the option that was ALREADY correctly marked, not a real
-- defect -- and were PUBLISHED via QuestionReviewService#publish (same
-- business logic as the real Admin UI). 3 sibling PENDING_REVIEW questions
-- from the same run (dev ids 399, 403, 407) were REJECTED in the same human
-- review pass for genuine content defects (399: asserted an unsupported
-- "custom delimiters slow down parsing" claim not stated in the lesson;
-- 403: incorrectly marked hasNext() as NOT a Scanner method, contradicting
-- the lesson; 407: single-answer framing ignored that the lesson also
-- treats FileNotFoundException/file-path handling as an important
-- consideration) and are intentionally NOT included here.
--
-- Data-quality fix (not a content override): questions 394-406's raw
-- OpenAI output for dev ids 397 and 401 contained LITERAL backslash-n
-- text sequences in code_snippet (and in 401's correct option text)
-- instead of real line breaks -- a generation/JSON-escaping artifact, not
-- present in any other topic's promoted questions. This was corrected by a
-- direct UPDATE in development (replacing literal backslash-n with a real
-- newline character) before writing this migration -- the values below
-- already reflect the corrected content; no wording/meaning/correct-answer
-- was changed.
--
-- These development IDs are DOCUMENTATION/PROVENANCE ONLY -- no development
-- id is used as a foreign key value anywhere below. topic_id is resolved by
-- Topic.slug (globally unique, stable across environments); question_option
-- rows reference the newly generated id of the INSERT immediately above them
-- via a WITH ... RETURNING id CTE, so this migration is correct regardless of
-- what this environment's own auto-generated ids turn out to be -- same
-- pattern as question-promotion/V431, V489, V520, and V521.
--
-- Duplicate-promotion safety (bkz. docs/known-constraints.md "Faz D"): this
-- project intentionally has no promoted_at column or unique constraint yet --
-- before writing a NEW promotion migration, grep existing
-- db/migration/question-promotion/*.sql header comments for these same
-- Development Question IDs to confirm they were not already promoted (done
-- for this migration -- no overlap with V431's ids 44-58, V489's string-topic
-- ids, or V520/V521's arrays ids 367-380).

-- Dev question id 394 (topic: scanner, language: en)
WITH new_question_394 AS (
    INSERT INTO question (topic_id, language, type, difficulty, status, source,
                           question, code_snippet, code_language, explanation,
                           reviewed_by, reviewed_at, created_at, updated_at)
    SELECT id, 'en', 'SINGLE_CHOICE', 'BEGINNER',
           'PUBLISHED', 'OPENAI',
           $$What is the primary purpose of the Scanner class in Java?$$, NULL, NULL,
           $$The Scanner class is primarily used to read input from various sources and tokenize that input into manageable pieces. It simplifies the process of parsing input compared to reading raw bytes or characters.$$, $$n8n-ai-judge$$, '2026-08-31 19:16:04.046567',
           now(), now()
    FROM topic WHERE slug = 'scanner'
    RETURNING id
)
INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
    SELECT id, $$To read raw bytes from an InputStream$$, FALSE, 0 FROM new_question_394
        UNION ALL SELECT id, $$To tokenize and read input from a text source$$, TRUE, 1 FROM new_question_394
        UNION ALL SELECT id, $$To perform complex mathematical operations$$, FALSE, 2 FROM new_question_394
        UNION ALL SELECT id, $$To manage file system operations$$, FALSE, 3 FROM new_question_394;

-- Dev question id 395 (topic: scanner, language: en)
