-- Dev question id 397 (topic: scanner, language: en, type: CODE_OUTPUT)
WITH new_question_397 AS (
    INSERT INTO question (topic_id, language, type, difficulty, status, source,
                           question, code_snippet, code_language, explanation,
                           reviewed_by, reviewed_at, created_at, updated_at)
    SELECT id, 'en', 'CODE_OUTPUT', 'BEGINNER',
           'PUBLISHED', 'OPENAI',
           $$What will be the output of the following code?$$,
           $$Scanner scanner = new Scanner(System.in);
int number = scanner.nextInt();
String line = scanner.nextLine();
System.out.println(line);$$, $$java$$,
           $$The output will be an empty string because nextInt() consumes the integer input but leaves the newline character in the input stream, which is then read by nextLine().$$, $$n8n-ai-judge$$, '2026-08-31 19:26:07.6487',
           now(), now()
    FROM topic WHERE slug = 'scanner'
    RETURNING id
)
INSERT INTO question_option (question_id, option_text, is_correct, sort_order)
    SELECT id, $$The integer value entered$$, FALSE, 0 FROM new_question_397
        UNION ALL SELECT id, $$An empty string$$, TRUE, 1 FROM new_question_397
        UNION ALL SELECT id, $$A prompt for the next input$$, FALSE, 2 FROM new_question_397
        UNION ALL SELECT id, $$An error message$$, FALSE, 3 FROM new_question_397;

